// Shared helpers for the site and the deck. All values come from window.ABCD
// (assets/data.js, generated by scripts/build_site.py).
(function () {
  const D = window.ABCD, S = D.spec, G = S.geometry;
  const chips = S.chips;
  const byGroup = g => chips.filter(c => c.group === g);
  const esc = s => String(s).replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));

  // 6x6 ArUco cell grid ('#' = black) -> SVG
  function markerSVG(rows) {
    let r = '';
    rows.forEach((row, y) => [...row].forEach((ch, x) => { if (ch === '#') r += `<rect x="${x}" y="${y}" width="1" height="1" fill="#000"/>`; }));
    return `<svg viewBox="-0.6 -0.6 7.2 7.2" shape-rendering="crispEdges"><rect x="-0.6" y="-0.6" width="7.2" height="7.2" fill="#fff"/>${r}</svg>`;
  }

  function markersHTML() {
    const ids = G.fiducial_aruco.ids, v1 = G.fiducial_aruco.v1_ids;
    const fig = (grid, label) => `<figure>${markerSVG(grid)}<figcaption>${label}</figcaption></figure>`;
    const order = ['TL', 'TR', 'BR', 'BL'];
    return `<div><h3>v1 · DICT_4X4_50 IDs ${order.map(k => v1[k]).join(', ')}</h3><div class="markers">${order.map(k => fig(G.fiducial_bits_v1[k], `${k} · id ${v1[k]}`)).join('')}</div></div>
      <div><h3>v2 · DICT_4X4_50 IDs ${order.map(k => ids[k]).join(', ')}</h3><div class="markers">${order.map(k => fig(G.fiducial_bits[k], `${k} · id ${ids[k]}`)).join('')}</div></div>`;
  }

  const CASES = { flat: 'Flat', persp_mild: 'Mild perspective', persp_strong: 'Strong perspective', rot15: 'Rotated 15°', rot180: 'Upside down (180°)' };
  function detectionTable() {
    const before = D.detection.before, after = D.detection.after;
    if (!after) return '<p class="muted">No detection results yet.</p>';
    const cell = (set, card, cs, fx) => {
      const r = set && set.rows.find(x => x.card === card && x.case === cs && x.fx === fx);
      if (!r) return '<td>–</td>';
      return `<td class="${r.ok ? 'ok' : 'bad'}">${r.ok ? '✓' : '✗'} ${r.err.toFixed(1)} px${r.ids ? ` · ${r.ids}/4 IDs · ${r.detected}` : ''}</td>`;
    };
    let rows = '';
    for (const cs of Object.keys(CASES)) for (const fx of ['plain', 'cast_blur']) {
      rows += `<tr><td>${CASES[cs]}${fx === 'cast_blur' ? ' + colour cast, noise, blur' : ''}</td>${cell(before, 'v1', cs, fx)}${cell(after, 'v1', cs, fx)}${cell(before, 'v2', cs, fx)}${cell(after, 'v2', cs, fx)}</tr>`;
    }
    const count = (set, card) => set ? `${set.rows.filter(r => r.card === card && r.ok).length}/${set.rows.filter(r => r.card === card).length}` : '–';
    return `<div class="table-wrap"><table><thead><tr><th>Synthetic photo</th><th>v1 · app before</th><th>v1 · app after</th><th>v2 · app before</th><th>v2 · app after</th></tr></thead>
      <tbody>${rows}<tr><th>Passed</th><th>${count(before, 'v1')}</th><th>${count(after, 'v1')}</th><th>${count(before, 'v2')}</th><th>${count(after, 'v2')}</th></tr></tbody></table></div>`;
  }

  function swatchList(group, cols, h = 44) {
    return `<div style="display:grid;grid-template-columns:repeat(${cols},1fr);gap:8px">${byGroup(group).map(c =>
      `<div style="font-size:.78rem;line-height:1.25"><div style="height:${h}px;border-radius:5px;background:${c.sRGB_D65};border:1px solid rgba(0,0,0,.2)"></div>
       <b>${c.id}</b> <span class="mono">${esc(c.munsell)}</span><br><span class="muted">${esc(c.label)}</span></div>`).join('')}</div>`;
  }

  // Fill <span data-k="..."> placeholders from the spec.
  function bindNumbers(root = document) {
    const swapped = chips.filter(c => c.munsell !== c.munsell_requested);
    const vals = {
      card: `${G.card_mm[0]} × ${G.card_mm[1]} mm`,
      nchips: chips.length,
      ncal: byGroup('calibration').length, nplant: byGroup('plant').length, nsoil: byGroup('soil').length, nramp: byGroup('neutral ramp').length,
      chipmm: `${chips[0].size_mm[0]} mm`, span: `${G.corner_span_cm.x} × ${G.corner_span_cm.y} cm`,
      nswapped: swapped.length, swapped: swapped.map(c => `${c.munsell_requested} → ${c.munsell}`).join(', '),
      maxde: Math.max(...chips.map(c => c.gamut_dE2000)).toFixed(2),
      werthn: D.werth.compared, werthd: D.werth.maxdiff, werthmiss: D.werth.missing.length,
      ids: Object.values(G.fiducial_aruco.ids).join(', '), v1ids: Object.values(G.fiducial_aruco.v1_ids).sort((a, b) => a - b).join(', '),
      pipeline: G.colour_pipeline,
    };
    root.querySelectorAll('[data-k]').forEach(el => { if (el.dataset.k in vals) el.textContent = vals[el.dataset.k]; });
  }

  window.ABCDUI = { D, S, G, chips, byGroup, esc, markerSVG, markersHTML, detectionTable, swatchList, bindNumbers };
})();
